static JsonSchemaValidator getDefaultValidator() {
		if (defaultValidator == null) {
			defaultValidator = JsonSchemaInternal.createDefaultValidator();
		}
		return defaultValidator;
	}

static JsonSchemaValidator createDefaultValidator() {
		AtomicReference<IllegalStateException> ex = new AtomicReference<>();
		return ServiceLoader.load(JsonSchemaValidatorSupplier.class).stream().flatMap(p -> {
			try {
				JsonSchemaValidatorSupplier supplier = p.get();
				return Stream.ofNullable(supplier);
			}
			catch (Exception e) {
				addException(ex, e);
				return Stream.empty();
			}
		}).flatMap(jsonMapperSupplier -> {
			try {
				return Stream.of(jsonMapperSupplier.get());
			}
			catch (Exception e) {
				addException(ex, e);
				return Stream.empty();
			}
		}).findFirst().orElseThrow(() -> {
			if (ex.get() != null) {
				return ex.get();
			}
			else {
				return new IllegalStateException("No default JsonSchemaValidatorSupplier implementation found");
			}
		});
	}

public static HttpRequest of(UrlBuilder url) {
        String host = url.getHost();
        if (!"github.com".equals(host)) {
            return new HttpRequestPlus(url);
        }

        Config config = ConfigUtil.CONFIG;
        String github = config.getGithub();
        Boolean customGithub = config.getCustomGithub();
        String customGithubUrl = config.getCustomGithubUrl();

        if (customGithub) {
            if (StrUtil.isBlank(customGithubUrl)) {
                log.info("未填写自定义github加速");
                return new HttpRequestPlus(url);
            }
            github = customGithubUrl;
        }

        if (StrUtil.isBlank(github) || github.equals("None")) {
            return new HttpRequestPlus(url);
        }

        // 处理github加速
        String newUrl = github + "/" + url;
        log.info("github 已加速: {}", newUrl);
        return new HttpRequestPlus(UrlBuilder.ofHttp(newUrl, StandardCharsets.UTF_8));
    }

