public static void sortFiles(List<RemoteFile> fileList) {
        // 使用Comparator自定义比较规则
        fileList.sort((f1, f2) -> {
            // 文件夹优先于文件
            if (f1.isDirectory() && !f2.isDirectory()) {
                return -1;
            } else if (!f1.isDirectory() && f2.isDirectory()) {
                return 1;
            } else {
                // 如果类型相同，则按名称排序
                return f1.getName().compareTo(f2.getName());
            }
        });
    }

