public Map<String, Object> getTemplateParameter() {
        if (CollUtil.isEmpty(templateParameter)) {
            return new HashMap<>();
        }
        Map<String, Object> map = new HashMap<>();
        // 参数转为String,飞书目前传其他类型报错
        this.templateParameter.forEach((k, v) -> {
            switch (v) {
                case Number ignored -> map.put(k, String.valueOf(v));
                case Date date ->
                    // yyyy-MM-dd HH:mm:ss
                        map.put(k, new DateTime(date).toString());
                case LocalDateTime localDateTime -> {
                    // yyyy-MM-dd HH:mm:ss
                    DateTime date = DateUtil.date(localDateTime);
                    map.put(k, date.toString());
                }
                case String string -> {
                    // err_msg: unsupported type of html tag
                    String replace = HtmlUtil.cleanHtmlTag(string);
                    map.put(k, replace);
                }
                case null, default -> map.put(k, v);
            }
        });
        return map;
    }

public static String encrypt(String text, String secretKey) {
        try {
            if (StringUtils.isEmpty(text)) {
                return text;
            }
            SecretKeySpec sks = new SecretKeySpec(secretKey.getBytes(StandardCharsets.UTF_8), ALGORITHM);
            Cipher cipher = Cipher.getInstance(TRANSFORMATION);
            cipher.init(Cipher.ENCRYPT_MODE, sks);
            byte[] encrypted = cipher.doFinal(text.getBytes());
            return Base64.encodeBase64String(encrypted);
        } catch (Exception ex) {
            log.warn("AES加密失败", ex);
            return text;
        }
    }

public static String decrypt(String encrypt, String secretKey) {
        try {
            SecretKeySpec sks = new SecretKeySpec(secretKey.getBytes(StandardCharsets.UTF_8), ALGORITHM);
            Cipher cipher = Cipher.getInstance(TRANSFORMATION);
            cipher.init(Cipher.DECRYPT_MODE, sks);
            byte[] original = cipher.doFinal(Base64.decodeBase64(encrypt));
            return new String(original);
        } catch (Exception ex) {
            log.warn("AES解密失败", ex);
            return encrypt;
        }
    }

@Override
    public void visitExpressionStatement(ExpressionStatement statement) {
        this.checkForbiddenCalls(statement.getExpression());
        super.visitExpressionStatement(statement);
    }

@Override
    public void visitMethodCallExpression(MethodCallExpression call) {
        this.checkMethodCall(call);
        super.visitMethodCallExpression(call);
    }

@Override
    public void visitStaticMethodCallExpression(StaticMethodCallExpression call) {
        this.checkStaticMethodCall(call);
        super.visitStaticMethodCallExpression(call);
    }

@Override
    public void visitConstructorCallExpression(ConstructorCallExpression call) {
        this.checkConstructorCall(call);
        super.visitConstructorCallExpression(call);
    }

private void checkForbiddenCalls(Expression expr) {
        if (expr instanceof MethodCallExpression) {
            this.checkMethodCall((MethodCallExpression) expr);
        } else if (expr instanceof StaticMethodCallExpression) {
            this.checkStaticMethodCall((StaticMethodCallExpression) expr);
        } else if (expr instanceof ConstructorCallExpression) {
            this.checkConstructorCall((ConstructorCallExpression) expr);
        }
    }

private void checkMethodCall(MethodCallExpression call) {
        Expression objectExpr = call.getObjectExpression();
        // 例如 new Test().test()
        if (objectExpr instanceof ConstructorCallExpression ctorCall) {
            checkConstructorCall(ctorCall);
            ClassNode constructedType = ctorCall.getType();
            this.checkClassMethodCall(constructedType, call.getMethodAsString(), call);
        }
        // 例如 variable.test()
        else if (objectExpr instanceof VariableExpression varExpr) {
            this.checkClassMethodCall(varExpr.getOriginType(), call.getMethodAsString(), call);
        }
        // 例如 Test.test()
        else if (objectExpr instanceof ClassExpression classExpr) {
            this.checkClassMethodCall(classExpr.getType(), call.getMethodAsString(), call);
        }
    }

private void checkStaticMethodCall(StaticMethodCallExpression call) {
        ClassNode declaringClass = call.getOwnerType();
        this.checkClassMethodCall(declaringClass, call.getMethod(), call);
    }

@Override
    public void before(AppLifecycleCommand command, List<SystemBootDataInit> systemBootBeforeInits) {
        if (!command.getOptions().isUpdateMeta()) {
            return;
        }
        // 系统初始化数据前置处理
        for (SystemBootDataInit systemBootDataInit : systemBootBeforeInits) {
            long start = System.currentTimeMillis();
            systemBootDataInit.init(command);
            log.info("{} system boot after cost time: {}ms", systemBootDataInit.getClass().getName(), System.currentTimeMillis() - start);
        }
    }

public boolean isSystemTableExist() {
        // 判断系统表是否存在
        String dsKey = DsApi.get().systemDsKey();
        String modelTableName = DataPrefixManager.tablePrefix(ModuleConstants.MODULE_SYSTEM, ModelTable.MODEL_MODEL, ModelTable.TABLE_NAME);
        boolean isExistTable = Dialects.component(TableMetaDialectService.class, dsKey).existTable(dsKey, modelTableName);
        if (!isExistTable) {
            log.debug(MessageFormat.format("System table [{0}] is not exists. DsKey:{1}", modelTableName, dsKey));
        }
        return isExistTable;
    }

@Override
    public void reload(AppLifecycleCommand command, List<ModuleDefinition> modules, List<ReloadDataInit> reloadDataInits) {
        if (!command.getOptions().isUpdateData()) {
            return;
        }
        if (CollectionUtils.isEmpty(modules)) {
            return;
        }
        for (ModuleDefinition reloadModule : modules) {
            for (ReloadDataInit reloadDataInit : reloadDataInits) {
                List<String> targetModules = reloadDataInit.modules();
                if (!CollectionUtils.isEmpty(targetModules) && !targetModules.contains(reloadModule.getModule())) {
                    continue;
                }
                long start = System.currentTimeMillis();
                reloadDataInit.reload(command, reloadModule.getLatestVersion());
                log.info("{} reload data init cost time: {}ms", reloadDataInit.getClass().getName(), System.currentTimeMillis() - start);
            }
        }
    }

