public int kthLargestIntegerQuickselect(int[] nums, int k) {
        return quickselect(nums, 0, nums.length - 1, k);
    }

private int quickselect(int[] nums, int left, int right, int k) {
        int n = nums.length;
        if (left >= right) return nums[left];
        int randomIndex = left + (int)(Math.random() * (right - left + 1));
        swap(nums, randomIndex, right);
        int pivotIndex = partition(nums, left, right);
        // If the pivot comes before 'n - k', the ('n - k')th smallest 
        // integer is somewhere to its right. Perform quickselect on the 
        // right part.
        if (pivotIndex < n - k) return quickselect(nums, pivotIndex + 1, right, k);
        // If the pivot comes after 'n - k', the ('n - k')th smallest integer
        // is somewhere to its left. Perform quickselect on the left part.
        else if (pivotIndex > n - k) return quickselect(nums, left, pivotIndex - 1, k);
        // If the pivot is at index 'n - k', it's the ('n - k')th smallest
        // integer.
        else return nums[pivotIndex];
    }

private int partition(int[] nums, int left, int right) {
        int pivot = nums[right];
        int lo = left;
        for (int i = left; i < right; i++) {
            if (nums[i] < pivot) {
                swap(nums, lo, i);
                lo++;
            }
        }
        swap(nums, lo, right);
        return lo;
    }

private void swap(int[] nums, int a, int b) {
        int tmp = nums[a];
        nums[a] = nums[b];
        nums[b] = tmp;
    }

public int[] sortArray(int[] nums) {
        quicksortOptimized(nums, 0, nums.length - 1);
        return nums;
    }

private void quicksortOptimized(int[] nums, int left, int right) {
        if (left >= right) return;
        // Choose a pivot at a random index.
        // Math.random() generate a double in [0.0, 1.0)
        // Scale the range from [0.0, 1.0) to [0, right - left + 1)
        int randomIndex = left + (int)(Math.random() * (right - left + 1));
        // Swap the randomly chosen pivot with the rightmost element to 
        // position the pivot at the rightmost index.
        swap(nums, randomIndex, right);
        int pivotIndex = partition(nums, left, right);
        quicksortOptimized(nums, left, pivotIndex - 1);
        quicksortOptimized(nums, pivotIndex + 1, right);
    }

public int longestChainOfConsecutiveNumbersBruteForce(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }
        int longestChain = 0;
        // Look for chains of consecutive numbers that start from each number.
        for (int num : nums) {
            int currentNum = num;
            int currentChain = 1;
            // Continue to find the next consecutive numbers in the chain.
            while (existInArray(nums, currentNum + 1)) {
                currentNum++;
                currentChain++;
            }
            longestChain = Math.max(longestChain, currentChain);
        }
        return longestChain;
    }

private boolean existInArray(int[] nums, int target) {
        for (int num : nums) {
            if (num == target) {
                return true;
            }
        }
        return false;
    }

public int longestChainOfConsecutiveNumbers(int[] nums) {
        if (nums == null || nums.length == 0) {
            return 0;
        }
        Set<Integer> numSet = new HashSet<>();
        for (int num : nums) {
            numSet.add(num);
        }
        int longestChain = 0;
        for (int num : numSet) {
            // If the current number is the smallest number in its chain, search for
            // the length of its chain.
            if (!numSet.contains(num - 1)) {
                int currentNum = num;
                int currentChain = 1;
                // Continue to find the next consecutive numbers in the chain.
                while (numSet.contains(currentNum + 1)) {
                    currentNum++;
                    currentChain++;
                }
                longestChain = Math.max(longestChain, currentChain);
            }
        }
        return longestChain;
    }

public int largestSquareInAMatrixOptimized(int[][] matrix) {
        if (matrix == null || matrix.length == 0 || matrix[0] == null || matrix[0].length == 0) {
            return 0;
        }
        int m = matrix.length;
        int n = matrix[0].length;
        int[] prevRow = new int[n];
        int maxLen = 0;
        // Iterate through the matrix.
        for (int i = 0; i < m; i++) {
            int[] currRow = new int[n];
            for (int j = 0; j < n; j++) {
                // Base cases: if we’re in row 0 or column 0, the largest square ending
                // here has a length of 1. This can be set by using the value in the
                // input matrix.
                if (i == 0 || j == 0) {
                    currRow[j] = matrix[i][j];
                } else {
                    if (matrix[i][j] == 1) {
                        // currRow[j] = 1 + min(left, top-left, top)
                        currRow[j] = 1 + Math.min(currRow[j - 1], Math.min(prevRow[j - 1], prevRow[j]));
                    }
                }
                maxLen = Math.max(maxLen, currRow[j]);
            }
            // Update 'prevRow' with 'currRow' values for the next iteration.
            prevRow = currRow;
        }
        return maxLen * maxLen;
    }

